/**
 * Per-pool-version id → identity aliases.
 *
 * When a bank re-bases (NCVEC 3-year cycle; ISED CA Advanced 2026), the OLD
 * shipped JSON is compared against the NEW parse; every question whose
 * content identity is unchanged between versions keeps its user progress via
 * the alias map (old id → the identity). Generated by scripts/emit-aliases
 * at pipeline time; this module just resolves lookups. A tiny inline
 * registry of historical versions lives on as data (generated, not authored).
 */

import type { ExamQuestion } from '../data/exam-banks.js';
import { contentIdentityFromQuestion } from './ident.js';

/**
 * Build an alias object for a pool version: nativeId → content identity.
 * Persist alongside the emitted bank version so re-base migrations can map
 * "which identity did old-id X point at?".
 */
export function buildAliases(versionTag: string, questions: ExamQuestion[]): {
  versionTag: string;
  aliases: Record<string, string>;
} {
  const aliases: Record<string, string> = {};
  for (const q of questions) {
    aliases[q.id] = contentIdentityFromQuestion(q);
  }
  return { versionTag, aliases };
}

/**
 * Resolve a native id through a chain of aliases (latest→oldest). Returns
 * null when the id is unknown to every version (a genuinely NEW question —
 * it gets a fresh progress record, correctly).
 */
export function resolveAlias(id: string, versions: { versionTag: string; aliases: Record<string, string> }[]): string | null {
  for (let i = versions.length - 1; i >= 0; i--) {
    const hit = versions[i]?.aliases[id];
    if (hit) return hit;
  }
  return null;
}
